import{_ as e,H as t,f as s,i}from"./chunks/framework.DIv0Dgmf.js";const u=JSON.parse('{"title":"第七章：多轮对话技巧","description":"学会通过多轮对话完善代码，掌握会话管理","frontmatter":{"title":"第七章：多轮对话技巧","description":"学会通过多轮对话完善代码，掌握会话管理"},"headers":[],"relativePath":"guide/2-basic-usage/7-multi-turn.md","filePath":"guide/2-basic-usage/7-multi-turn.md"}'),n={name:"guide/2-basic-usage/7-multi-turn.md"};function l(o,a,p,d,r,h){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="第七章-多轮对话技巧" tabindex="-1">第七章：多轮对话技巧 <a class="header-anchor" href="#第七章-多轮对话技巧" aria-label="Permalink to &quot;第七章：多轮对话技巧&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会通过多轮对话一步步完善代码，并掌握会话管理技巧。</p></div><h2 id="为什么多轮对话更有效" tabindex="-1">为什么多轮对话更有效？ <a class="header-anchor" href="#为什么多轮对话更有效" aria-label="Permalink to &quot;为什么多轮对话更有效？&quot;">​</a></h2><p>想象你要建一座房子：</p><ul><li><strong>一次性描述</strong>：给我建一座房子 → 出来的可能不是你想要的</li><li><strong>一步步来</strong>：先打地基 → 地基好了，继续砌墙 → 墙好了，继续装修 → 每一步都能调整</li></ul><p>多轮对话就是这种方式，让 Claude 一步步帮你完善。</p><h2 id="场景演练-做一个待办事项" tabindex="-1">场景演练：做一个待办事项 <a class="header-anchor" href="#场景演练-做一个待办事项" aria-label="Permalink to &quot;场景演练：做一个待办事项&quot;">​</a></h2><h3 id="第一轮-基础结构" tabindex="-1">第一轮：基础结构 <a class="header-anchor" href="#第一轮-基础结构" aria-label="Permalink to &quot;第一轮：基础结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一个待办事项的基本结构</span></span></code></pre></div><p>Claude 会给你一个基本框架。</p><h3 id="第二轮-添加功能" tabindex="-1">第二轮：添加功能 <a class="header-anchor" href="#第二轮-添加功能" aria-label="Permalink to &quot;第二轮：添加功能&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>添加&quot;标记完成&quot;功能</span></span></code></pre></div><p>Claude 在现有基础上继续开发。</p><h3 id="第三轮-添加保存" tabindex="-1">第三轮：添加保存 <a class="header-anchor" href="#第三轮-添加保存" aria-label="Permalink to &quot;第三轮：添加保存&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>添加&quot;保存到文件&quot;功能</span></span></code></pre></div><p>Claude 继续完善。</p><h2 id="上下文的作用" tabindex="-1">上下文的作用 <a class="header-anchor" href="#上下文的作用" aria-label="Permalink to &quot;上下文的作用&quot;">​</a></h2><p>Claude 记得对话历史，所以：</p><ul><li>你不需要重复之前说的话</li><li>可以随时问&quot;现在的进度怎么样了&quot;</li></ul><h2 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to &quot;会话管理&quot;">​</a></h2><h3 id="token-限制" tabindex="-1">Token 限制 <a class="header-anchor" href="#token-限制" aria-label="Permalink to &quot;Token 限制&quot;">​</a></h3><p>每个对话有 Token 限制（通常数万）。超过限制后：</p><ul><li>早期对话可能被&quot;遗忘&quot;</li><li>响应会变慢</li></ul><h3 id="什么时候开新对话" tabindex="-1">什么时候开新对话？ <a class="header-anchor" href="#什么时候开新对话" aria-label="Permalink to &quot;什么时候开新对话？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>对话超过 50 条</td><td>开新对话</td></tr><tr><td>换完全不相关的任务</td><td>开新对话</td></tr><tr><td>想重新开始</td><td>开新对话</td></tr><tr><td>深入同一个任务</td><td>保持当前对话</td></tr></tbody></table><h3 id="高效交接" tabindex="-1">高效交接 <a class="header-anchor" href="#高效交接" aria-label="Permalink to &quot;高效交接&quot;">​</a></h3><p>开新对话时，简要描述背景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在做一个 Flask 博客项目，已经：</span></span>
<span class="line"><span>1. 完成了用户认证（JWT）</span></span>
<span class="line"><span>2. 完成了文章 CRUD</span></span>
<span class="line"><span>3. 使用 PostgreSQL 数据库</span></span>
<span class="line"><span></span></span>
<span class="line"><span>现在要添加评论功能...</span></span></code></pre></div><h2 id="记忆系统" tabindex="-1">记忆系统 <a class="header-anchor" href="#记忆系统" aria-label="Permalink to &quot;记忆系统&quot;">​</a></h2><p>Claude Code 有持久记忆功能：</p><h3 id="查看记忆" tabindex="-1">查看记忆 <a class="header-anchor" href="#查看记忆" aria-label="Permalink to &quot;查看记忆&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/memory</span></span></code></pre></div><p>会显示当前已保存的记忆。</p><h3 id="添加记忆" tabindex="-1">添加记忆 <a class="header-anchor" href="#添加记忆" aria-label="Permalink to &quot;添加记忆&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/memory</span></span>
<span class="line"><span>记住：这是一个 Vue 3 + Pinia 项目</span></span></code></pre></div><h3 id="记忆的作用" tabindex="-1">记忆的作用 <a class="header-anchor" href="#记忆的作用" aria-label="Permalink to &quot;记忆的作用&quot;">​</a></h3><p>记忆让你不需要每次都重复背景信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一次：记住这是 Next.js 项目</span></span>
<span class="line"><span>之后：直接说&quot;帮我在 About 页面添加...&quot;</span></span>
<span class="line"><span>Claude 会知道是 Next.js 项目</span></span></code></pre></div><h3 id="清除记忆" tabindex="-1">清除记忆 <a class="header-anchor" href="#清除记忆" aria-label="Permalink to &quot;清除记忆&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/memory clear</span></span></code></pre></div><h2 id="清空对话" tabindex="-1">清空对话 <a class="header-anchor" href="#清空对话" aria-label="Permalink to &quot;清空对话&quot;">​</a></h2><p>如果对话乱了但想保持上下文：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/clear</span></span></code></pre></div><p>这会清空对话历史，但<strong>不会</strong>清除记忆。</p><h2 id="压缩上下文" tabindex="-1">压缩上下文 <a class="header-anchor" href="#压缩上下文" aria-label="Permalink to &quot;压缩上下文&quot;">​</a></h2><p>对话太长时，Claude 可以压缩上下文：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact</span></span></code></pre></div><p>会尝试精简历史记录，保留关键信息。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>会基本的对话操作。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 忘了之前的对话？</strong></p><p>A: 超过一定长度可能遗忘。可以用 <code>/memory</code> 保存重要上下文，或开新对话并描述背景。</p><p><strong>Q: 对话乱了？</strong></p><p>A: 输入 <code>/clear</code> 清空重来。如果想保持一些信息，先用 <code>/memory</code> 保存。</p><p><strong>Q: 记忆和对话有什么区别？</strong></p><p>A: 记忆是持久的，跨对话存在。对话历史只在当前会话有效。</p><p><strong>Q: 怎么知道 Token 快用完了？</strong></p><p>A: 对话变慢、响应变短时可能接近限制。开新对话是更好的选择。</p><p><strong>Q: 能让 Claude 只记住特定的规则吗？</strong></p><p>A: 可以，用 <code>/memory</code> 添加精确的规则描述。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>用多轮对话方式，让 Claude 帮你做一个&quot;记账本&quot;程序</li><li>使用 <code>/memory</code> 保存项目背景，然后开新对话测试</li><li>对话太长时用 <code>/compact</code> 压缩上下文</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何用 Claude 帮你调试代码。</p><p><a href="/claude-code-guide/guide/3-practical-workflows/08-debugging.html">👉 第八章：调试和错误处理</a></p>`,66)])])}const b=e(n,[["render",l]]);export{u as __pageData,b as default};
